// fayl: app/api/webhooks/payment/route.ts
import { createHmac, timingSafeEqual } from "node:crypto"

export async function POST(req: Request) {
  const raw = await req.text()
  const expected = createHmac("sha256", process.env.WEBHOOK_SECRET!).update(raw).digest("hex")
  const got = req.headers.get("x-signature") ?? ""
  const valid = got.length === expected.length && timingSafeEqual(Buffer.from(got), Buffer.from(expected))
  if (!valid) return Response.json({ error: "imzo noto'g'ri" }, { status: 400 })
  return Response.json({ ok: true, event: JSON.parse(raw).event })
}

