const seen = new Map<string, object>()
let created = 0

export async function POST(req: Request, { params }: { params: Promise<{ orderId: string }> }) {
  const key = req.headers.get("idempotency-key")
  if (!key) return Response.json({ error: "Idempotency-Key kerak" }, { status: 400 })
  if (seen.has(key)) return Response.json({ ...seen.get(key), replay: true })
  const payment = { orderId: (await params).orderId, paymentId: ++created }
  seen.set(key, payment)
  return Response.json(payment, { status: 201 })
}

